function attrs(
  strength: number,
  dexterity: number,
  constitution: number,
  intelligence: number,
  wisdom: number,
  charisma: number,
): Record<AttributeId, number> {
  return { strength, dexterity, constitution, intelligence, wisdom, charisma }
}

