    abilities: [
      {
        id: "bone-ship-skeleton-crew",
        name: "Tripulação Esquelética",
        originalName: "Skeleton Crew",
        actionType: "passive",
        description: "O navio de ossos é impulsionado não por uma única mente, mas pela consciência coletiva das almas de marinheiros mortos. O navio é imune a efeitos mentais que visam apenas um número específico de criaturas. Ainda é afetado por efeitos mentais que afetam todas as criaturas em uma área. Qualquer criatura que tentar se comunicar com o navio por telepatia ou ler seus pensamentos ouve os gritos agonizantes e suspiros da tripulação, e é alvo de uma magia de 9º círculo (salvaguarda de Vontade CD 41).\n O navio anima membros esqueléticos da tripulação a partir de seus próprios ossos, armando-os com cutelos enferrujados ou outros armamentos para atacar quem se aproximar do navio. Essas entidades têm aparências correspondentes às que as almas presas tinham em vida, mas não são indivíduos de verdade; qualquer coisa que as visar na verdade visa o navio de ossos do qual fazem parte.\n Centenas de gemas de alma decoram o exterior do navio, cada uma contendo uma alma. Essas gemas podem conter almas de criaturas de até 16º nível, e não têm valor. Se o navio for destruído, todas essas gemas se estilhaçam, libertando as almas.",
      },
      {
        id: "bone-ship-trawl-for-bones",
        name: "Varrer Ossos do Mar",
        originalName: "Trawl for Bones",
        actionType: "passive",
        description: "O navio de ossos passa 1 dia recolhendo ossos do mar e se restaura a PV completos.",
      },
      {
        id: "bone-ship-all-around-vision",
        name: "Visão Total",
        originalName: "All-Around Vision",
        actionType: "passive",
        description: "A criatura vê em todas as direções ao mesmo tempo e portanto não pode ser flanqueada.",
      },
      {
        id: "bone-ship-blood-wake",
        name: "Esteira de Sangue",
        originalName: "Blood Wake",
        actionType: "passive",
        description: "9 m. A água revolta ao redor do navio de ossos tingida de vermelho por sangue que vaza. Uma criatura viva que entrar na água na aura vê visões de si mesma se afogando no sangue e deve tentar uma salvaguarda de Vontade CD 37. Em uma falha, a criatura fica Amedrontada 2 (Amedrontada 4 em uma falha crítica) e Atordoada 1, e sofre penalidade de status de –4 em testes de Atletismo para Nadar. Independentemente do resultado da salvaguarda, a criatura fica temporariamente imune por 1 hora.",
      },
      {
        id: "bone-ship-cannonade",
        name: "Canhoneira",
        originalName: "Cannonade",
        actionType: "two",
        description: "O navio de ossos faz quatro Golpes de canhão de ossos, cada um visando uma criatura diferente.",
      },
      {
        id: "bone-ship-chain-shot",
        name: "Tiro de Corrente",
        originalName: "Chain Shot",
        actionType: "one",
        description: "O navio de ossos faz um Golpe especial de canhão de ossos, disparando uma corrente feita de ossos. Uma criatura atingida por este Golpe fica agarrada pela corrente (Escapar CD 41). O navio de ossos pode usar ações Interagir para puxar uma criatura agarrada 4,5 m por ação gasta, e quando o navio se move, puxa a criatura agarrada junto.",
      },
      {
        id: "bone-ship-crew-s-call",
        name: "Chamado da Tripulação",
        originalName: "Crew's Call",
        actionType: "two",
        description: "A tripulação solta um grito angustiado em uníssono. Isso é uma magia em uma emanação de 30 m (salvaguarda de Fortitude CD 39). Além disso, qualquer criatura a até 1,5 m do navio é automaticamente agarrada pela tripulação. O navio não pode usar Chamado da Tripulação novamente por 1d4+1 rodadas.",
      },
      {
        id: "bone-ship-trample",
        name: "Arrastar pela Quilha",
        originalName: "Keelhaul",
        actionType: "three",
        description: "Como Pisotear (Enorme ou menor, casco, salvaguarda de Reflexos CD 43), mas o navio de ossos Nada até o dobro de seu Deslocamento de nado em vez de Distanciar, e cada criatura que falhar na salvaguarda também é arrastada para debaixo do navio. O MJ coloca cada criatura arrastada em um espaço subaquático adjacente ao navio de ossos ao final do movimento do navio. Trample",
      },
      {
        id: "bone-ship-pressgang-soul",
        name: "Recrutar Alma",
        originalName: "Pressgang Soul",
        actionType: "one",
        description: "O navio de ossos conjura . O alvo deve ter morrido devido ao assalto do navio de ossos ou por afogamento. A alma da criatura passa a fazer parte da tripulação fantasmagórica. Uma nova gema de alma cresce no navio, e o navio de ossos fica Acelerado por 1 minuto. Pode usar a ação extra apenas para Golpe ou Nadar.",
      },
    ],
    summary: "Navio feito de osso e ódio. O rasto é água vermelha e nenhum vivo a bordo.",
