        description: "Se um capuchim causar dano a uma criatura com seu Golpe de mandíbulas, a criatura ganha uma bênção e uma maldição que duram 1d6 horas.\n Enquanto a bênção dobra o tempo que a criatura afetada pode prender a respiração, a maldição impõe uma versão acelerada da dependência de umidade do capuchim, causando 1d6 de dano a cada 10 minutos que a criatura amaldiçoada fica sem água.\n Uma criatura amaldiçoada pode se imergir completamente em água como uma atividade de 3 ações e tentar uma salvaguarda de Fortitude CD 17, encerrando bênção e maldição em um sucesso.",
