        description: "O Trapaceiro Imortal pode estender seus sentidos através de qualquer coiote, raposa ou corvo no Universo, tornando-o seu animal sensorial. Não pode manter atenção em mais de três animais sensoriais ao mesmo tempo. Pode falar através de seus animais sensoriais, mas apenas em uma frase curta por animal de no máximo duas palavras. Tem pouco controle sobre as ações de seus animais sensoriais, embora geralmente ajam de forma consistente com seus desejos, a menos que tenham motivo específico para não fazê-lo. Ao estender seus sentidos através de um animal sensorial, pode usá-lo para determinar linha de efeito para qualquer uma de suas magias ou habilidades.",
