        originalName: "Suffocated by a Thousand Breaths",
        actionType: "passive",
        description: "9 m. A influência de Vulot que rouba o fôlego irradia de seu corpo, fazendo as vítimas sentirem que estão sendo sufocadas. Qualquer criatura que comece seu turno na aura deve tentar salvaguarda de Fortitude CD 41. Sucesso crítico A criatura não é afetada.\n Sucesso A criatura fica sem fôlego e Enjoada até o início de seu próximo turno.\n Falha A criatura acha muito difícil recuperar o fôlego. Não pode falar nem usar ações auditivas até o início de seu próximo turno; isso a impede de conjurar magias que não tenham o traço sutil.\n Falha crítica Todo o ar imediatamente sai dos pulmões da criatura e ela começa a sufocar. Quando obtiver sucesso na salvaguarda para recuperar a consciência ao final de seu turno, fica Debilitada até descansar uma noite inteira.",
