        description: "Custo 1 Ponto Mítico Efeito Vulot faz um Golpe de garra. Em um acerto, Vulot tenta um teste de Enganação contra a CD de Vontade do alvo para roubar o rosto dessa criatura; em um acerto crítico, Vulot trata o resultado de seu teste de Enganação como um grau de sucesso maior. Em um sucesso, Vulot rouba o rosto do alvo por 1d4 rodadas (1 minuto em um sucesso crítico); uma criatura cujo rosto foi roubado não é considerada aliada por nenhuma criatura.",
