        description: "Como objetos normais, uma pipa animada tem Dureza. Essa Dureza reduz qualquer dano que sofra em uma quantidade igual à Dureza. Quando uma pipa animada é reduzida a menos da metade de seus PV, ou imediatamente ao sofrer dano de um acerto crítico, sua armadura de constructo se quebra e sua Classe de Armadura é reduzida para 13.",
