        description: "O jiidon assume a forma de qualquer criatura humanoide Média ou Pequena cujas unhas ou fragmentos semelhantes tenha consumido na última semana, ganhando os efeitos de uma magia de 3º círculo de disfarce ilusório para se passar por essa criatura por 8 horas; isso é um efeito de metamorfose em vez de ilusão. Depois que um jiidon se transformou em uma criatura assim, deve comer as unhas dessa criatura novamente para se transformar nela outra vez. Se um jiidon consumir as unhas de um humanoide específico três noites seguidas, pode assumir a forma desse humanoide à vontade, mas não pode mais usar esta habilidade para imitar qualquer outro humanoide.",
