        description: "O joseung saja olha nos olhos de uma criatura a até 9 m e remove memórias inconvenientes ou dolorosas que a impedem de seguir em frente para a morte. O alvo sabe que o joseung saja tentou alterar sua memória e pode tentar uma salvaguarda de Vontade para resistir. Alvos voluntários recebem os efeitos de uma falha crítica.\n Sucesso crítico O alvo não é afetado.\n Sucesso O alvo sofre 2d10 de dano e fica Embotado 2 por 1 rodada.\n Falha O alvo sofre 4d10 de dano e fica Embotado 2 por 1 semana.\n Falha crítica O alvo perde todas as emoções e memórias dolorosas, deixando uma névoa indistinta. Se o alvo for um ijhyeojin, todas as suas memórias são ceifadas e ele se torna um joseung saja.",
